 async function hideReaderGuide(){if(guideBusy||settings.readerGuideHidden)return;guideBusy=true;try{clearTimeout(saveTimer);const next={...settings,readerGuideHidden:true};await api('/api/settings','PUT',next);settings={...settings,readerGuideHidden:true};try{localStorage.setItem('pereplet-settings',JSON.stringify(settings))}catch{};selectedBookIds=selectedBookIds.filter(id=>!books.find(b=>b.id===id)?.is_reader_guide);if(selected?.is_reader_guide)selected=null;if(seriesFilter==='Ваш Переплёт'&&!visibleLibraryBooks.some(b=>!b.is_reader_guide&&b.series===seriesFilter))seriesFilter='';guideHint=true;if(window.innerWidth<=850)sidebarOpen=true;await tick();const help=document.querySelector<HTMLButtonElement>('.guide-help>button');help?.focus({preventScroll:true});help?.scrollIntoView({block:'nearest'});clearTimeout(guideHintTimer);guideHintTimer=setTimeout(()=>guideHint=false,6500);}catch(e){notify(e.message)}finally{guideBusy=false}}
 async function openReaderGuide(){if(guideBusy||statusBusy||bulkBusy||archiveBusy||mediaTypeBusy)return;guideBusy=true;guideHint=false;try{const book=await api<Book>('/api/help/reader-guide','POST',{});if(books.some(b=>b.id===book.id))updateBook(book);else books=[...books,book];sidebarOpen=false;await openBook(book)}catch(e){notify(e.message)}finally{guideBusy=false}}
 function updateBook(b:Book){books=books.map(old=>old.id===b.id?{...old,...b}:old);if(selected?.id===b.id)selected={...selected,...b}}
 function measureContinue(node:HTMLElement){const measure=(width=node.clientWidth)=>{const slots=continueCapacity(width);if(slots!==continueSlots)continueSlots=slots};measure();const observer=new ResizeObserver(entries=>measure(entries[0].contentRect.width));observer.observe(node);return{destroy(){observer.disconnect()}}}
 function saveSettings(s:any){if(s.layout&&s.layout!==settings.layout&&s.width===undefined)s=layoutSettings(settings,s.layout);settings={...settings,...s};try{localStorage.setItem('pereplet-settings',JSON.stringify(settings))}catch{};clearTimeout(saveTimer);saveTimer=setTimeout(()=>api('/api/settings','PUT',settings).catch(e=>notify(e.message)),400)}
 function writePreferences(id:string,value:any){const write=preferenceWrites.catch(()=>{}).then(async()=>{const updated=await api<Book>(`/api/books/${id}`,'PATCH',{reading_settings:value});updateBook(updated)});preferenceWrites=write;return write}
 function flushReaderPreferences(){clearTimeout(preferencesTimer);const pending=pendingPreferences;pendingPreferences=null;return pending?writePreferences(pending.id,pending.value):preferenceWrites}
 function saveReaderSettings(value:any){if(useGlobalSettings){saveSettings(value);return}readerPreferences={...readerPreferences,appearance:appearanceOf(value)};const outside=settingsOutsideAppearance(value);if(Object.keys(outside).some(key=>outside[key]!==settings[key]))saveSettings(outside);if(reading){pendingPreferences={id:reading.id,value:readerPreferences};clearTimeout(preferencesTimer);preferencesTimer=setTimeout(()=>void flushReaderPreferences().catch(e=>notify(e.message)),350)}}
 async function changeSettingsScope(global:boolean){if(!reading)return settings;clearTimeout(preferencesTimer);pendingPreferences=null;const next=scopePreferences(readerPreferences,global,activeReaderSettings);await writePreferences(reading.id,next);readerPreferences=next;return readerSettings(settings,next)}
 function navigate(next:string){localQuery='';groupSortOverride=false;collectionFiltersOpen=false;archiveType='';selectingBooks=false;selectedBookIds=[];seriesAssignmentOpen=false;seriesAssignmentIds=null;checkpointCatalog();opdsAhead.clear();opdsCache.cancelPrefetch();cancelPageLoad();savedPanel=null;browseGeneration++;feedLoading=false;view=next;query='';authorFilter='';seriesFilter='';statusFilter='';letter='';selected=null;remoteSelected=null;sidebarOpen=false;}
 function sortDirection(key:string){return effectiveSort===key?(effectiveSortDirection||(key==='recent'||key==='progress'?'desc':'asc')):'asc'}
 function compareBooks(a:Book,b:Book,key:string,direction?:string){const compare=(x:any,y:any)=>String(x||'').localeCompare(String(y||''),'ru',{numeric:true});let value=key==='title'?compare(a.title,b.title):key==='author'?compare(a.author||a.authors?.[0],b.author||b.authors?.[0]):key==='series'?compare(a.series,b.series)||compareSeriesPositions(a.series_index,b.series_index,(direction==='desc'?-1:1))*(direction==='desc'?-1:1):key==='progress'?Number(a.progress)-Number(b.progress):key==='format'?compare(a.format,b.format):compare(a.added_at,b.added_at);return value*((direction||(key==='recent'||key==='progress'?'desc':'asc'))==='desc'?-1:1)||compare(a.title,b.title)}
 function setLibrarySort(key:string,direction=key==='recent'||key==='progress'?'desc':'asc'){groupSortOverride=true;if(seriesSortScope)seriesSortOverride={scope:seriesSortScope,key,direction};else saveSettings({sort:key,sortDirection:direction})}
