 function changeAuthor(value:string){authorFilter=value;const next=libraryFacets(metadataBooks,{...localFilters,author:value});if(seriesFilter&&(seriesFilter==='__no_series__'?!next.hasNoSeries:!next.series.includes(seriesFilter)))seriesFilter=''}
 function resetLocalFilters(){query='';localQuery='';authorFilter='';seriesFilter='';statusFilter='';letter='';archiveType='';saveSettings({libraryMetadataFilters:{...defaultOpdsFilters}})}
