 async function setStatus(b:Book,status:string){if(statusBusy||bulkBusy||archiveBusy||mediaTypeBusy)return;statusBusy=true;try{const updated=await api<Book>(`/api/books/${b.id}`,'PATCH',{status});updateBook(updated)}catch(e){notify(e.message)}finally{statusBusy=false}}
