 async function setMediaType(b:Book,type:string){if(mediaTypeBusy||archiveBusy||bulkBusy||statusBusy)return;if(type!=='book'&&type!=='comic')return;mediaTypeBusy=true;try{const updated=await api<Book>(`/api/books/${b.id}`,'PATCH',{media_type:type});updateBook(updated);notify(type==='comic'?'Издание перенесено в «Комиксы»':'Издание перенесено в «Библиотеку»')}catch(e){notify(e.message)}finally{mediaTypeBusy=false}}
 async function setArchived(b:Book,archived:boolean){if(archiveBusy||bulkBusy||mediaTypeBusy||statusBusy)return;archiveBusy=true;try{const updated=await api<Book>(`/api/books/${b.id}`,'PATCH',{archived});updateBook(updated);selectedBookIds=selectedBookIds.filter(id=>id!==b.id);notify(archived?'Издание убрано в архив. Файл и прогресс сохранены.':`Издание восстановлено в «${mediaType(updated)==='comic'?'Комиксы':'Библиотеку'}».`)}catch(e){notify(e.message)}finally{archiveBusy=false}}
 async function bulkChange(values:{archived?:boolean;media_type?:string;status?:ReadingStatus}){if(bulkBusy||archiveBusy||mediaTypeBusy||statusBusy||!selectedBookIds.length)return;bulkBusy=true;const ids=[...selectedBookIds],origin=view;let changed=0;const failed:string[]=[];let firstError='';try{for(const id of ids){try{const updated=await api<Book>(`/api/books/${id}`,'PATCH',values);updateBook(updated);changed++}catch(e){failed.push(id);firstError ||= e.message}}if(view===origin){selectedBookIds=failed;if(!failed.length)selectingBooks=false}notify(failed.length?`Изменено: ${changed}. Не удалось: ${failed.length}. ${firstError}`:values.archived===true?`В архив убрано: ${changed}. Файлы и прогресс сохранены.`:values.archived===false?`Восстановлено из архива: ${changed}.`:values.status?`Статус «${statusNames[values.status]}» установлен: ${changed}.`:`Перенесено в «${values.media_type==='comic'?'Комиксы':'Библиотеку'}»: ${changed}.`)}finally{bulkBusy=false}}
 async function removeBook(){if(!deleteBook)return;try{await api(`/api/books/${deleteBook.id}`,'DELETE');books=books.filter(b=>b.id!==deleteBook.id);selected=null;deleteBook=null;notify('Книга удалена из библиотеки')}catch(e){notify(e.message)}}
 async function importFiles(input:File[]|FileList){const files=Array.from(input).filter(f=>/\.(fb2|epub|zip|txt|pdf|cbz|cbr)$/i.test(f.name));if(!files.length){notify('Добавьте FB2, FB2.zip, EPUB, TXT, PDF, CBZ или CBR');return;}importBusy=true;let count=0,duplicates=0,failures:string[]=[],warnings:string[]=[];try{for(let i=0;i<files.length;i+=20){importMessage=`Добавляем книги: ${Math.min(i+20,files.length)} из ${files.length}`;const data=new FormData();files.slice(i,i+20).forEach(f=>data.append('files',f,f.name));const result=await api('/api/import','POST',data);count+=result.imported?.length||0;warnings.push(...(result.imported||[]).flatMap((book:Book)=>book.import_warnings||[]));duplicates+=result.duplicates?.length||0;failures.push(...(result.errors||[]).map((e:any)=>typeof e==='string'?e:e.error||e.message||JSON.stringify(e)));}await refresh();notify(`Добавлено: ${count}${duplicates?`. Уже есть: ${duplicates}`:''}${failures.length?`. Ошибки: ${failures.length}. ${failures[0]}`:''}${warnings.length?`. ${warnings[0]}`:''}`);}catch(e){notify(e.message)}finally{importBusy=false;importMessage='';if(fileInput)fileInput.value='';if(folderInput)folderInput.value='';}}
 async function entryFiles(entry:any):Promise<File[]>{if(entry.isFile)return new Promise(resolve=>entry.file((f:File)=>resolve([f]),()=>resolve([])));if(entry.isDirectory){const reader=entry.createReader();let items:any[]=[];while(true){const batch:any[]=await new Promise(resolve=>reader.readEntries(resolve,()=>resolve([])));if(!batch.length)break;items.push(...batch)}return(await Promise.all(items.map(entryFiles))).flat();}return[]}
 async function drop(e:DragEvent){e.preventDefault();dragging=false;dragDepth=0;if(importBusy)return;const entries=Array.from(e.dataTransfer?.items||[]).map((x:any)=>x.webkitGetAsEntry?.()).filter(Boolean);const files=entries.length?(await Promise.all(entries.map(entryFiles))).flat():Array.from(e.dataTransfer?.files||[]);await importFiles(files)}
 function dragOver(e:DragEvent){if(Array.from(e.dataTransfer?.types||[]).includes('Files')){e.preventDefault();dragging=true;}}
 function persistCatalogs(){historyVersion++;try{localStorage.setItem('pereplet-opds-browser',opdsHistory.serialize())}catch{}}
 function checkpointCatalog(){clearTimeout(scrollSaveTimer);if(view==='catalogs'&&currentCatalog&&feed){opdsHistory.checkpoint(currentCatalog.id,query,libraryMain?.scrollTop||0,opdsPages?.requests,opdsFilter);persistCatalogs()}}
