 function setMetadataFilters(value:OpdsFilterState){if(currentCatalog)saveSettings({opdsFiltersByCatalog:{...settings.opdsFiltersByCatalog,[currentCatalog.id]:{...value}}});void tick().then(maybeLoadMore)}
 function resetCatalogFilters(){setOpdsFilter('');setMetadataFilters({...defaultOpdsFilters})}
 function setOpdsFilter(value:string){opdsFilter=value;checkpointCatalog();if(value)opdsAhead.clear();else{warmAhead();void tick().then(maybeLoadMore)}}
 function rememberCurrentSearch(force=false){const value=query.trim();if(!value)return;const key=`${searchScope}\0${value.replace(/\s+/gu,' ').toLocaleLowerCase()}`;if(force||key!==lastRememberedSearch)rememberSearch(searchScope,value);lastRememberedSearch=key}
 function selectPastSearch(value:string){query=value;if(view==='catalogs')searchCatalog();else rememberCurrentSearch(true)}
 function submitSearch(){searchHistory?.close();if(view==='catalogs')searchCatalog();else rememberCurrentSearch(true)}
 function cancelPageLoad(){pageRequest++;pagesLoading=false}
 function maybeLoadMore(){if(view==='catalogs'&&!feed?.search_results&&!reading&&!savedPanel&&!feedLoading&&!feedError&&!opdsFilter&&!pagesLoading&&!pageError&&!batchBusy&&opdsPages?.canAutoAppend&&libraryMain&&libraryMain.scrollHeight-libraryMain.scrollTop-libraryMain.clientHeight<480)void loadMorePages()}
 async function loadMorePages(manual=false){
  if(view!=='catalogs'||!currentCatalog||!opdsPages?.canAppend||feedLoading||pagesLoading||(!manual&&!opdsPages.canAutoAppend))return;
  const pages=opdsPages,catalog=currentCatalog,generation=browseGeneration,token=++pageRequest,url=pages.feed.next!,retry=!!pageError;
  pagesLoading=true;pageError='';
  try{
   const next=await opdsCache.get(url,'',{refresh:retry});
   if(generation!==browseGeneration||token!==pageRequest||pages!==opdsPages)return;
   pages.append(url,next);opdsPages=pages;feed=pages.feed;opdsPageStore.save(catalog.id,pages);checkpointCatalog();warmAhead();
   await tick();
  }catch(e){if(generation===browseGeneration&&token===pageRequest&&e.name!=='AbortError')pageError=e.message}
  finally{if(token===pageRequest){pagesLoading=false;if(!pageError)maybeLoadMore()}}
 }
 async function visitCatalog(request:{catalog:Catalog;url:string;requestQuery?:string;displayQuery?:string;scroll?:number;mode?:NavigationCommit;refresh?:boolean;flTab?:FlibustaTab;flSearch?:FlibustaSearchKind;flSeriesName?:string;section?:string;restoreTitle?:string;pages?:string[];filter?:string;contextUrl?:string}){
  checkpointCatalog();opdsAhead.clear();cancelPageLoad();view='catalogs';const generation=++browseGeneration;lastBrowse=request;feedLoading=true;feedError='';pageError='';remoteSelected=null;savedPanel=null;
  try{
   const load=(url:string,search='')=>{if(generation!==browseGeneration)return Promise.reject(new DOMException('Переход отменён','AbortError'));const snapshot=!request.refresh&&(typeof request.mode==='number'||request.mode==='replace')?opdsCache.readSnapshot(url,search):null;return snapshot?Promise.resolve(snapshot):opdsCache.get(url,search,{refresh:request.refresh})};
   let result:Feed,root=flibustaRoots[request.catalog.id];
   let special=isFlibustaCatalog(request.catalog.url,root);
   if(special&&!root){root=await load(request.catalog.url);if(generation!==browseGeneration)return;flibustaRoots={...flibustaRoots,[request.catalog.id]:root}}
   if(special&&request.flSeriesName)result=await findFlibustaSeries(root,request.flSeriesName,load);
   else if(special&&(request.flSearch||(/\/search(?:[?]|$)/.test(request.url)&&new URL(request.url).searchParams.has('searchType')))){
    const kind=request.flSearch||(new URL(request.url).searchParams.get('searchType')==='authors'?'authors':'books');
    const term=request.requestQuery||request.displayQuery||new URL(request.url).searchParams.get('searchTerm')||'';
    result=kind==='series'?await load(request.url,term):await searchFlibustaBoth(root,kind,term,load);
   }
   else if(special&&request.flTab)result=await resolveFlibustaTab(request.flTab,load);
   else result=await load(request.url,request.requestQuery||'');
   if(generation!==browseGeneration)return;
   if(!special&&isFlibustaCatalog(request.catalog.url,result)&&result.url===request.catalog.url){special=true;root=result;flibustaRoots={...flibustaRoots,[request.catalog.id]:root}}
   if(special&&!result.search_results){if(getFeedArea(result,root)==='root'){const tab=flibustaTabs(root).find(item=>item.id==='new');if(tab)result=await resolveFlibustaTab(tab,load)}else result=await resolveFlibustaFeed(result,load)}
   if(generation!==browseGeneration)return;
   if(special&&!result.search_results)result=await restoreFlibustaContext(result,load,request.contextUrl);
   if(generation!==browseGeneration)return;
   if(special&&request.restoreTitle)result={...result,title:request.restoreTitle};
   const cachedPages=!request.refresh&&!result.search_results?opdsPageStore.read(request.catalog.id,result.url,request.pages||[]):null;
   const pages=cachedPages||await restorePages(result,request.pages||[],load,error=>{if(generation===browseGeneration)pageError=error instanceof Error?error.message:String(error)});
   if(generation!==browseGeneration)return;
   if(request.restoreTitle||result.context_url)pages.update(value=>({...value,...(request.restoreTitle?{title:request.restoreTitle}:{}),...(result.context_url?{context_url:result.context_url,navigation:[...new Map([...value.navigation,...result.navigation].map(item=>[item.url,item])).values()]}:{})}));
   currentCatalog=request.catalog;opdsPages=pages;feed=pages.feed;opdsPageStore.save(currentCatalog.id,pages);query=request.displayQuery??request.requestQuery??result.search_results?.query??'';opdsFilter=request.flSeriesName||request.filter||'';if(special&&!result.search_results)opdsCache.update(value=>value.url===result.url?{...value,title:result.title,navigation:result.navigation,context_url:result.context_url}:value);
   if(special){const area=getFeedArea(result,root);flibustaCurrentTab=request.flTab?.id||(['new','authors','series','genres'].includes(area)?area as FlibustaTabId:area==='author'?'authors':request.section as FlibustaTabId||'');if(result.search_results||request.flSearch==='books')flibustaCurrentTab='';flibustaSearchKind=request.flSearch||((area==='author'||area==='authors')?'authors':'books')}
   const session=opdsHistory.session(currentCatalog.id,currentCatalog.url);if(result.search||root?.search)session.search=result.search||root.search;catalogSearch=session.search||null;
   opdsHistory.commit(currentCatalog.id,{url:result.url,requestUrl:special?result.url:request.url,requestQuery:special?'':request.requestQuery||'',query,scroll:request.scroll||0,title:result.title,timestamp:Date.now(),pages:[...pages.requests],filter:opdsFilter,contextUrl:result.context_url,...(special&&flibustaCurrentTab?{tab:flibustaCurrentTab}:{})},request.mode??'push');persistCatalogs();view='catalogs';warmAhead();
   await tick();if(generation===browseGeneration&&libraryMain)libraryMain.scrollTop=request.scroll||0;
  }catch(e){if(generation===browseGeneration&&e.name!=='AbortError')feedError=e.message}
  finally{if(generation===browseGeneration){feedLoading=false;await tick();maybeLoadMore()}}
