 function browse(url:string){if(currentCatalog)visitCatalog({catalog:currentCatalog,url,section:flibustaActive?flibustaCurrentTab:undefined,...(authorContext&&url!==currentCatalog.url&&!permanentTabs.some(tab=>tab.url===url)?{contextUrl:feed.context_url}:{})})}
 function openFlibustaTab(tab:FlibustaTab){if(currentCatalog)visitCatalog({catalog:currentCatalog,url:tab.url,flTab:tab})}
 function searchCatalog(){searchHistory?.close();if(currentCatalog&&activeSearch&&query.trim()){rememberCurrentSearch(true);visitCatalog({catalog:currentCatalog,url:activeSearch.url,requestQuery:query.trim(),...(flibustaActive?{flSearch:flibustaSearchKind}: {})})}}
 function openRelated(destination:RelatedDestination){
  if(!currentCatalog)return;
  if(destination.url){visitCatalog({catalog:currentCatalog,url:destination.url,section:destination.kind==='author'?'authors':'series'});return}
  if(flibustaActive&&destination.kind==='series'){visitCatalog({catalog:currentCatalog,url:currentCatalog.url,flSeriesName:destination.name,section:'series'});return}
  if(activeSearch)visitCatalog({catalog:currentCatalog,url:activeSearch.url,requestQuery:destination.name,...(flibustaActive?{flSearch:'authors' as FlibustaSearchKind}:{})});
 }
 function retryBrowse(){if(lastBrowse)visitCatalog({...lastBrowse,refresh:true})}
 function moveFeed(delta:number){if(!currentCatalog)return;const target=opdsHistory.target(currentCatalog.id,delta);if(target)visitCatalog({catalog:currentCatalog,url:target.location.requestUrl,requestQuery:target.location.requestQuery,displayQuery:target.location.query,scroll:target.location.scroll,mode:target.index,section:target.location.tab,restoreTitle:target.location.title,pages:target.location.pages,filter:target.location.filter,contextUrl:target.location.contextUrl})}
 function backFeed(){moveFeed(-1)}
