 function refreshFeed(){if(!currentCatalog||!feed)return;const location=opdsHistory.current(currentCatalog.id);visitCatalog({catalog:currentCatalog,url:location?.requestUrl||feed.url,requestQuery:location?.requestQuery,displayQuery:query,scroll:libraryMain?.scrollTop||0,mode:'replace',refresh:true,section:location?.tab,restoreTitle:location?.title,pages:opdsPages?.requests,filter:opdsFilter,contextUrl:location?.contextUrl})}
 function catalogList(){navigate('catalogs');feed=null;opdsPages=null;currentCatalog=null;catalogSearch=null;feedError=''}
 function openCatalog(c:Catalog){checkpointCatalog();opdsHistory.session(c.id,c.url);const location=opdsHistory.current(c.id);visitCatalog({catalog:c,url:location?.requestUrl||c.url,requestQuery:location?.requestQuery,displayQuery:location?.query||'',scroll:location?.scroll||0,mode:location?'replace':'push',section:location?.tab,restoreTitle:location?.title,pages:location?.pages,filter:location?.filter,contextUrl:location?.contextUrl})}
 function toggleBookmark(){if(!currentCatalog)return;checkpointCatalog();const added=opdsHistory.toggleBookmark(currentCatalog.id);persistCatalogs();notify(added?'Раздел добавлен в закладки':'Закладка удалена')}
 function removeBookmark(location:SavedLocation){opdsHistory.removeBookmark(location);persistCatalogs()}
 function openSaved(location:SavedLocation){if(currentCatalog)visitCatalog({catalog:currentCatalog,url:location.requestUrl,requestQuery:location.requestQuery,displayQuery:location.query,scroll:location.scroll,section:location.tab,restoreTitle:location.title,pages:location.pages,filter:location.filter,contextUrl:location.contextUrl})}
 function showSaved(kind:'history'|'bookmarks'){checkpointCatalog();browseGeneration++;feedLoading=false;cancelPageLoad();opdsAhead.clear();opdsCache.cancelPrefetch();savedPanel=kind}
 function prefetch(url:string){if(!batchBusy)opdsCache.prefetch(url)}
 async function addCatalog(){if(!catalogName.trim()||!catalogUrl.trim())return;catalogSaving=true;try{await api('/api/catalogs','POST',{name:catalogName.trim(),url:catalogUrl.trim()});catalogs=await api('/api/catalogs');catalogModal=false;catalogName='';catalogUrl='';notify('Каталог добавлен')}catch(e){notify(e.message)}finally{catalogSaving=false}}
 async function removeCatalog(c:Catalog){try{await api(`/api/catalogs/${c.id}`,'DELETE');catalogs=catalogs.filter(x=>x.id!==c.id);opdsHistory.removeCatalog(c.id);persistCatalogs();if(currentCatalog?.id===c.id)catalogList();}catch(e){notify(e.message)}}
 function acquisition(e:Entry){return preferredAcquisition(e)}
 function markDownloaded(url:string,localId:string){const mark=(entry:Entry)=>entry.acquisitions?.some(link=>link.url===url)?{...entry,local_book_id:localId}:entry;const update=(value:Feed)=>({...value,entries:value.entries.map(mark)});opdsCache.update(update);opdsPageStore.update(update);if(opdsPages){opdsPages.update(update);feed=opdsPages.feed}else if(feed)feed=update(feed);if(remoteSelected)remoteSelected=mark(remoteSelected)}
 async function downloadEntry(e:Entry){const a=acquisition(e);if(!a)throw new Error('Нет поддерживаемого формата');downloads={...downloads,[e.id]:true};try{const result=await api('/api/opds/download','POST',{url:a.url,title:e.title,type:a.type});if(result.book?.id){markDownloaded(a.url,result.book.id);books=books.some(b=>b.id===result.book.id)?books: [...books,result.book]}return result;}finally{downloads={...downloads,[e.id]:false}}}
 async function download(e:Entry){if(e.local_book_id){await openBook({id:e.local_book_id} as Book);return;}if(!acquisition(e)||downloads[e.id]||batchBusy)return;try{const result=await downloadEntry(e);await refresh();notify(result.duplicate?'Эта книга уже есть в вашей библиотеке':`«${e.title}» теперь в библиотеке`);return result.book?.id as string|undefined;}catch(err){notify(err.message)}}
 async function downloadAll(){if(!feed||batchBusy)return;const first=feed.search_results?.books||feed,filters={...metadataFilters},substring=opdsFilter.toLocaleLowerCase();batchTitle=feed.title;batchBusy=true;batchCancelRequested=false;opdsAhead.clear();opdsCache.cancelPrefetch();try{batch=await downloadSection(first,{include:entry=>matchesOpdsFilters(entry,filters)&&(!substring||[entry.title,...(entry.authors||[]),...(entry.series||[]).map(item=>item.name)].join(' ').toLocaleLowerCase().includes(substring)),load:url=>opdsCache.get(url),download:downloadEntry,cancelled:()=>batchCancelRequested,progress:state=>batch=state});await refresh()}catch(e){notify(e.message)}finally{batchBusy=false}}
