 function keydown(e:KeyboardEvent){if(e.defaultPrevented||reading||seriesAssignmentOpen)return;if(e.key==='Escape'&&searchHistoryOpen){e.preventDefault();searchHistory?.close(true);return;}if((e.ctrlKey||e.metaKey)&&(e.code==='KeyF'||e.key.toLowerCase()==='f')){e.preventDefault();searchInput?.focus();searchHistory?.show()}if(e.key==='Escape'){savedPanel=null;settingsOpen=false;catalogModal=false;deleteBook=null;selected=null;remoteSelected=null;sidebarOpen=false}}
 onMount(()=>{const offDesktop=onDesktopClose(async()=>{checkpointCatalog();clearTimeout(saveTimer);if(reading?.is_reader_guide)settings={...settings,readerGuideHidden:true};await flushReaderPreferences();await api('/api/settings','PUT',settings);});try{opdsHistory=new OpdsHistory(localStorage.getItem('pereplet-opds-browser'));historyVersion++}catch{};try{const stored=localStorage.getItem('pereplet-settings');if(stored)settings=normalizeSettings(JSON.parse(stored))}catch{};(async()=>{try{await initApi();const result=await Promise.allSettled([api<Book[]>('/api/books'),api('/api/settings'),api<Catalog[]>('/api/catalogs')]);if(result[0].status==='fulfilled')books=result[0].value;else throw result[0].reason;if(result[1].status==='fulfilled')settings=normalizeSettings(result[1].value);if(result[2].status==='fulfilled')catalogs=result[2].value;}catch(e){error=e.message}finally{loading=false}})();window.addEventListener('keydown',keydown);window.addEventListener('beforeunload',checkpointCatalog);return()=>{offDesktop();checkpointCatalog();opdsAhead.dispose();opdsCache.dispose();window.removeEventListener('keydown',keydown);window.removeEventListener('beforeunload',checkpointCatalog);clearTimeout(scrollSaveTimer);clearTimeout(toastTimer);clearTimeout(saveTimer);clearTimeout(guideHintTimer)}});
</script>
