   {:else if loading}<div class="empty-state"><BookOpen size={45} weight="light"/><p>Открываем библиотеку…</p></div>
   {:else if view==='catalogs'}
    {#if !feed&&!feedLoading}<div class="catalog-list">{#each catalogs as c}<article class="catalog-card"><button class="catalog-open" aria-label={`Открыть каталог ${c.name}`} onclick={()=>openCatalog(c)}><Globe size={34} weight="light"/><span class="catalog-card-meta"><span class="catalog-card-title">{c.name}</span><span class="catalog-card-url">{c.url}</span></span><span class="catalog-card-action">Открыть<ArrowRight size={19}/></span></button><button class="icon-button" title="Убрать каталог" aria-label={`Убрать каталог ${c.name}`} onclick={()=>removeCatalog(c)}><X size={18}/></button></article>{/each}<button class="add-catalog-card" onclick={()=>catalogModal=true}><Plus size={25}/><strong>Добавить OPDS-каталог</strong><span>Вставьте адрес знакомой вам библиотеки</span></button></div>{/if}
    {#if currentCatalog||feedLoading}<div class="opds-browser-bar">
     <div class="opds-global-row">
      {#if flibustaActive&&permanentTabs.length}<nav class="flibusta-tabs" aria-label="Разделы Флибусты">{#each permanentTabs as tab}<button class:active={flibustaCurrentTab===tab.id} aria-current={flibustaCurrentTab===tab.id?'page':undefined} onmouseenter={()=>prefetch(tab.url)} onfocus={()=>prefetch(tab.url)} onmouseleave={()=>opdsCache.cancelHover()} onblur={()=>opdsCache.cancelHover()} onclick={()=>openFlibustaTab(tab)}>{tab.label}</button>{/each}</nav>{:else}<span class="opds-catalog-name">{currentCatalog?.name||'Каталог'}</span>{/if}
      <div class="opds-saved-actions"><button disabled={!currentCatalog} onclick={()=>showSaved('history')}><ClockCounterClockwise size={17}/>История</button><button disabled={!currentCatalog} onclick={()=>showSaved('bookmarks')}><BookmarkSimple size={17}/>Сохранённые разделы</button></div>
     </div>
     <div class="catalog-navigation opds-toolbar">
      <button class="icon-button" title="Назад" aria-label="Назад в каталоге" disabled={!backTarget} onclick={backFeed}><ArrowLeft size={20}/></button>
      <button class="icon-button" title="Вперёд" aria-label="Вперёд в каталоге" disabled={!forwardTarget} onclick={()=>moveFeed(1)}><ArrowRight size={20}/></button>
      <button class="icon-button" title="На уровень выше" aria-label="На уровень выше" disabled={!feed?.up} onclick={()=>feed?.up&&browse(feed.up)}><ArrowUp size={20}/></button>
      <button class="icon-button" title="Начало каталога" aria-label="В начало каталога" disabled={!currentCatalog} onclick={rootFeed}><House size={20}/></button>
      <button class="icon-button" title="Обновить раздел" aria-label="Обновить раздел каталога" disabled={!currentCatalog||feedLoading} onclick={refreshFeed}><ArrowClockwise size={20}/></button>
      <div class="opds-location"><span>{currentCatalog?.name||lastBrowse?.catalog?.name||'Каталог'}</span><CaretRight size={14}/><strong title={feed?.title||''}>{feed?.title||'Открываем каталог…'}</strong><button class="icon-button opds-bookmark-current" title={bookmarked?'Удалить закладку':'Добавить текущий раздел в закладки'} aria-label={bookmarked?'Удалить закладку':'Добавить текущий раздел в закладки'} aria-pressed={bookmarked} disabled={!feed||!currentCatalog||feedLoading} onclick={toggleBookmark}><BookmarkSimple size={18} weight={bookmarked?'fill':'regular'}/></button></div>
     </div>
     {#if authorNavigation.length}<nav class="opds-author-context" aria-label="Книги этого автора"><span>У автора</span>{#each authorNavigation as item (item.url)}<button onmouseenter={()=>prefetch(item.url)} onfocus={()=>prefetch(item.url)} onmouseleave={()=>opdsCache.cancelHover()} onblur={()=>opdsCache.cancelHover()} onclick={()=>browse(item.url)}>{item.title==='Книги по сериям'?'Серии этого автора':item.title==='Книги вне серий'?'Вне серий':item.title==='Книги по дате поступления'?'По дате поступления':item.title==='Книги по алфавиту'?'Все книги':item.title}</button>{/each}</nav>{/if}
     {#if feed}<div class="opds-collection-toolbar">
      <label class="opds-list-filter"><MagnifyingGlass size={17}/><input aria-label={feed.entries.length?'В этом списке':'Фильтр разделов'} placeholder="В этом списке…" value={opdsFilter} oninput={e=>setOpdsFilter(e.currentTarget.value)} maxlength="500"/>{#if opdsFilter}<button class="icon-button" aria-label="Очистить фильтр списка" onclick={()=>setOpdsFilter('')}><X size={15}/></button>{/if}</label>
      <OpdsFilters filters={metadataFilters} onchange={setMetadataFilters}/><span class="opds-loaded-count" aria-live="polite">{feed.search_results?`Книг: ${feed.entries.length} · Авторов: ${feed.search_results.authors?.navigation.filter(item=>/\/author\/[^/]+\/?$/.test(new URL(item.url).pathname)).length||0}`:feed.entries.length?(opdsFilter||metadataFilterCount?`${remoteEntries.length} из ${feed.entries.length}`:`${feed.entries.length} книг`):`${visibleNavigation.length} разделов`}</span>{#if feed.entries.length}<button class="secondary opds-group-toggle" aria-pressed={!!settings.opdsGroupBySeries} onclick={()=>saveSettings({opdsGroupBySeries:!settings.opdsGroupBySeries})}><Stack size={17}/>По сериям</button>
      <div class="segmented opds-view-switch" aria-label="Вид книг каталога"><button title="Обложки" aria-label="Каталог: обложки" class:active={settings.opdsView==='grid'} aria-pressed={settings.opdsView==='grid'} onclick={()=>saveSettings({opdsView:'grid'})}><SquaresFour size={18}/></button><button title="Список" aria-label="Каталог: список" class:active={settings.opdsView==='list'} aria-pressed={settings.opdsView==='list'} onclick={()=>saveSettings({opdsView:'list'})}><List size={18}/></button><button title="Таблица" aria-label="Каталог: таблица" class:active={settings.opdsView==='table'} aria-pressed={settings.opdsView==='table'} onclick={()=>saveSettings({opdsView:'table'})}><Stack size={18}/></button></div>
      {#if settings.opdsView==='grid'}<label class="cover-size-control opds-cover-size" title="Размер обложек"><SquaresFour size={17}/><input type="range" min="120" max="230" step="10" value={settings.opdsCoverSize} oninput={e=>saveSettings({opdsCoverSize:+e.currentTarget.value})} aria-label="Размер обложек каталога"/></label>{/if}
      <button class="opds-download-all" disabled={batchBusy||feedLoading} title="Скачать книги текущего раздела и следующих страниц с учётом фильтров. До 500 книг / 50 страниц" onclick={downloadAll}><Download size={17}/>{metadataFilterCount||opdsFilter?'Скачать подходящие':'Скачать всё'}</button>{/if}
     </div>{/if}
     <div class="opds-loading-strip" role="status">{#if feedLoading}<CloudArrowDown size={14}/><span>Открываем раздел…</span>{/if}</div>
    </div>{/if}
    {#if batch}<section class="opds-batch" aria-label="Скачивание раздела"><div><strong>{batchBusy?(batchCancelRequested?'Завершаем текущий запрос…':batch.phase==='collecting'?'Собираем книги раздела…':'Скачиваем книги…'):batch.phase==='cancelled'?'Скачивание остановлено':'Скачивание завершено'}</strong><span title={batchTitle}>{batchTitle}</span>{#if batchBusy}<button disabled={batchCancelRequested} onclick={cancelBatch}>Остановить</button>{:else}<button class="icon-button" aria-label="Скрыть результат скачивания" onclick={()=>batch=null}><X size={18}/></button>{/if}</div><p>{batch.phase==='collecting'?`Страниц: ${batch.pages} · найдено книг: ${batch.total}`:`Добавлено: ${batch.downloaded} · пропущено: ${batch.skipped} · ошибок: ${batch.failed} · обработано: ${batch.processed} из ${batch.total}`}</p><progress max={Math.max(batch.total,1)} value={batch.phase==='collecting'?undefined:batch.processed}></progress>{#if batch.currentTitle}<p class="opds-batch-current">{batch.currentTitle}</p>{/if}<small>Только текущий раздел и следующие страницы. За один запуск — до 500 книг / 50 страниц. Книги из библиотеки и неподдерживаемые форматы пропускаются.</small>{#if batch.limited}<p class="opds-limit">Достигнут предел запуска. Остальные книги этого раздела не загружены.</p>{/if}{#if batch.errors.length}<details><summary>Подробности ошибок · {batch.failed}</summary><ul>{#each batch.errors as message}<li>{message}</li>{/each}</ul></details>{/if}</section>{/if}
    {#if feedError}<div class="inline-error" role="alert"><WarningCircle size={21}/><div><strong>Не удалось открыть раздел каталога</strong><p>{feedError}</p></div><button onclick={retryBrowse}>Повторить</button></div>{/if}
    {#if feed}<div class="opds-content" class:is-loading={feedLoading} aria-busy={feedLoading}>
     {#if !feed.entries.length&&contentNavigation.length}<div class="section-title"><h2>{flibustaDirectory?(flibustaCurrentTab==='authors'?'Авторы':flibustaCurrentTab==='series'?'Серии':'Жанры'):'Разделы каталога'}</h2></div>{#if metadataFilterCount}<p class="muted small">Пустые серии скрываются после загрузки их книг. Непроверенные разделы остаются видимыми.</p>{/if}{/if}
     {#if feed.search_results}<OpdsSearchResults grouped={!!settings.opdsGroupBySeries} result={feed.search_results} first={flibustaSearchKind==='authors'?'authors':'books'} filter={opdsFilter} filters={metadataFilters} view={settings.opdsView||'grid'} coverSize={settings.opdsCoverSize||160} {downloads} {batchBusy} selectedId={remoteSelected?.id||''} load={url=>opdsCache.get(url)} onselect={entry=>remoteSelected=entry} ondownload={download} onbrowse={browse} onretry={searchCatalog}/>{:else}
     {#if flibustaDirectory}
      {#if flibustaAlphabet.length}<div class="alphabet flibusta-alphabet">{#each flibustaAlphabet as item}<button onmouseenter={()=>prefetch(item.url)} onfocus={()=>prefetch(item.url)} onmouseleave={()=>opdsCache.cancelHover()} onblur={()=>opdsCache.cancelHover()} onclick={()=>browse(item.url)}>{item.title}</button>{/each}</div>{/if}
      <div class="flibusta-directory">{#each flibustaRows as item (item.url)}<button onmouseenter={()=>prefetch(item.url)} onfocus={()=>prefetch(item.url)} onmouseleave={()=>opdsCache.cancelHover()} onblur={()=>opdsCache.cancelHover()} onclick={()=>browse(item.url)}><span>{item.title}</span><CaretRight size={17}/></button>{/each}</div>
      {#if !flibustaRows.length&&(opdsFilter||metadataFilterCount)}<p class="muted small">В загруженных разделах совпадений нет.{feed.next?' Ещё разделы можно подгрузить кнопкой «Показать ещё».':''}</p>{/if}
     {:else if contentNavigation.length}
      {#if feed.entries.length}<div class="section-title"><h2>Разделы каталога</h2></div>{/if}
      <div class="catalog-sections">{#each visibleNavigation as n (n.url)}<button onmouseenter={()=>prefetch(n.url)} onfocus={()=>prefetch(n.url)} onmouseleave={()=>opdsCache.cancelHover()} onblur={()=>opdsCache.cancelHover()} onclick={()=>browse(n.url)}>{n.title}<CaretRight size={17}/></button>{/each}</div>
      {#if !visibleNavigation.length&&(opdsFilter||metadataFilterCount)}<p class="muted small">В загруженных разделах совпадений нет.{feed.next?' Ещё разделы можно подгрузить кнопкой «Показать ещё».':''}</p>{/if}
     {/if}
     {#if remoteEntries.length}{#if settings.opdsGroupBySeries}{#each remoteGroups as group (group.name)}<section class="remote-series-group" aria-label={group.name||'Без серии'}><h2>{group.name||'Без серии'}<span>{group.entries.length}</span></h2><RemoteBooks seriesScope={group.name?{url:feed.url,title:`Книги в серии ${group.name}`}:undefined} entries={group.entries} view={settings.opdsView||'grid'} coverSize={settings.opdsCoverSize||160} {downloads} {batchBusy} selectedId={remoteSelected?.id||''} onselect={entry=>remoteSelected=entry} ondownload={download}/></section>{/each}{:else}<RemoteBooks seriesScope={feed?{url:feed.url,title:feed.title}:undefined} entries={remoteEntries} view={settings.opdsView||'grid'} coverSize={settings.opdsCoverSize||160} {downloads} {batchBusy} selectedId={remoteSelected?.id||''} onselect={entry=>remoteSelected=entry} ondownload={download}/>{/if}{:else if (opdsFilter||metadataFilterCount)&&feed.entries.length}<div class="empty-state" role="status"><MagnifyingGlass size={35}/><p>В загруженных книгах совпадений нет.</p><button class="text-button" onclick={resetCatalogFilters}>Сбросить фильтры</button></div>{:else if !contentNavigation.length&&!authorNavigation.length}<div class="empty-state" role="status"><MagnifyingGlass size={35}/><p>{query?'По этому запросу каталог не вернул книг или разделов.':'Каталог вернул пустой раздел.'}</p></div>{/if}
     {#if opdsPages&&(feed.next||opdsPages.previous||opdsPages.pageCount>1)}
      <section class="opds-pagination" aria-label="Страницы каталога" aria-busy={pagesLoading}>
       <div class="opds-pagination-status" aria-live="polite"><span>Показано {feed.entries.length||contentNavigation.length} · страниц: {opdsPages.pageCount}</span>{#if pagesLoading}<span>Загружаем продолжение…</span>{:else if !feed.next}<span>Все записи раздела загружены</span>{:else if !opdsPages.canAppend}<span>{opdsPages.pageCount>=PAGE_LIMIT?'Показано 20 страниц.':'Достигнут предел записей на экране.'} Продолжите кнопкой «Следующая страница».</span>{:else if opdsPages.pageCount>=AUTO_PAGE_LIMIT}<span>Автоподгрузка приостановлена. Продолжение — кнопкой ниже.</span>{:else if opdsFilter}<span>Фильтр действует на загруженный список. Продолжение — кнопкой «Показать ещё».</span>{:else}<span>Следующие записи появятся при прокрутке</span>{/if}</div>
       {#if pageError}<div class="opds-page-error" role="alert"><WarningCircle size={18}/><span>{pageError}</span><button class="text-button" disabled={pagesLoading||feedLoading} onclick={()=>loadMorePages(true)}>Повторить подгрузку</button></div>{/if}
       <div class="opds-pagination-controls">
        <button class="text-button" disabled={!opdsPages.previous||feedLoading} onclick={()=>browse(opdsPages.previous)}><ArrowLeft size={18}/>Предыдущая страница</button>
        {#if feed.next&&opdsPages.canAppend}<button class="load-more" disabled={pagesLoading||feedLoading} onclick={()=>loadMorePages(true)}>{pagesLoading?'Загружаем…':'Показать ещё'}</button>{/if}
        <button class="text-button" disabled={!feed.next||feedLoading} onmouseenter={()=>feed.next&&prefetch(feed.next)} onfocus={()=>feed.next&&prefetch(feed.next)} onmouseleave={()=>opdsCache.cancelHover()} onblur={()=>opdsCache.cancelHover()} onclick={()=>browse(feed.next)}>Следующая страница<ArrowRight size={18}/></button>
       </div>
      </section>
     {/if}
     {/if}
    </div>{/if}
   {:else if directoryMode}
    <div class="directory-toolbar"><h2>{view==='authors'?'Указатель авторов':comicView?'Указатель серий комиксов':'Указатель серий'}</h2><span>{visibleDirectory.length} из {directoryItems.length}</span></div>
    <div class="alphabet directory-alphabet" aria-label="Алфавитный указатель"><button class:active={!letter} onclick={()=>letter=''}>Все</button>{#each directoryAlphabet as char}<button class:active={letter===char} onclick={()=>letter=letter===char?'':char}>{char}</button>{/each}</div>
    {#if visibleDirectory.length}<div class="directory-grid">{#each visibleDirectory as item}<button class="directory-entry" onclick={()=>openDirectory(item.key)}><span class="directory-label">{item.name}</span><span class="directory-count">{comicView?'Комиксов':'Книг'}: {item.count}</span><CaretRight size={18}/></button>{/each}</div>{:else}<div class="empty-state"><MagnifyingGlass size={38}/><h2>{directoryItems.length?'Ничего не найдено':'Здесь пока нет изданий'}</h2><p>{directoryItems.length?'Попробуйте другую букву или измените поиск.':comicView?'Добавьте комиксы — их серии появятся в этом указателе.':'Добавьте книги — указатель заполнится автоматически.'}</p>{#if letter||query}<button onclick={()=>{letter='';query=''}}>Показать все</button>{/if}</div>{/if}
   {:else}
    {#if view==='authors'||view==='series'||view==='comic-series'}<div class="directory-breadcrumb"><button class="text-button" onclick={backDirectory}><ArrowLeft size={18}/>{view==='authors'?'Все авторы':comicView?'Все серии комиксов':'Все серии'}</button><CaretRight size={15}/><span>{pageTitle}</span></div>{/if}

    <div class="collection-controls" class:filters-open={collectionFiltersOpen}>
     <div class="collection-browser-row">
      <label class="opds-list-filter local-list-filter"><MagnifyingGlass size={17}/><input bind:value={localQuery} aria-label="В этом списке" placeholder="В этом списке…" maxlength="500"/>{#if localQuery}<button class="icon-button" aria-label="Очистить фильтр списка" onclick={()=>localQuery=''}><X size={15}/></button>{/if}</label>
      <span class="opds-loaded-count" aria-live="polite">{shown.length}{shown.length!==viewCount?` из ${viewCount}`:' на полке'}</span>
      <OpdsFilters filters={localMetadataFilters} label="Фильтры библиотеки" sourceNote="По метаданным книг. Издания без указанных авторов тоже показываются." idPrefix="library-filter" onchange={value=>saveSettings({libraryMetadataFilters:value})}/>
      {#if !seriesFilter}<button class="secondary local-group-toggle" aria-pressed={groupedLibrary} onclick={()=>{groupSortOverride=false;saveSettings(view==='library'?{libraryGrouping:groupedLibrary?'none':'series'}:{libraryGroupSeries:!settings.libraryGroupSeries})}}><Stack size={17}/>По сериям</button>{/if}
      {#if view==='library'}<button class="secondary local-group-toggle" aria-pressed={groupedByAuthor} onclick={()=>{groupSortOverride=false;saveSettings({libraryGrouping:groupedByAuthor?'none':'author'})}}><Users size={17}/>По авторам</button>{/if}
      <div class="segmented local-view-switch" aria-label="Вид библиотеки"><button title="Полки" aria-label="Вид полками" class:active={settings.view==='shelf'} aria-pressed={settings.view==='shelf'} onclick={()=>saveSettings({view:'shelf'})}><Books size={18}/></button><button title="Обложки" aria-label="Вид обложками" class:active={settings.view==='grid'} aria-pressed={settings.view==='grid'} onclick={()=>saveSettings({view:'grid'})}><SquaresFour size={18}/></button><button title="Список" aria-label="Вид списком" class:active={settings.view==='list'} aria-pressed={settings.view==='list'} onclick={()=>saveSettings({view:'list'})}><List size={18}/></button><button title="Таблица" aria-label="Вид таблицей" class:active={settings.view==='table'} aria-pressed={settings.view==='table'} onclick={()=>saveSettings({view:'table'})}><Stack size={18}/></button></div>

      <button class="compact-filter-toggle" aria-label="Фильтры и сортировка" aria-expanded={collectionFiltersOpen} aria-controls="collection-filter-fields" onclick={()=>collectionFiltersOpen=!collectionFiltersOpen}><SlidersHorizontal size={17}/><span>Уточнить</span>{#if authorFilter||seriesFilter||statusFilter||archiveType}<span class="filter-dot" aria-label="Есть активные фильтры"></span>{/if}</button>
     </div>
     {#if selectingBooks}<div class="selection-toolbar" aria-label="Выбранные издания"><strong>Выбрано: {selectedBookIds.length}</strong><button class="text-button" disabled={bulkBusy||statusBusy} onclick={()=>selectedBookIds=shown.map(b=>b.id)}>Выбрать показанные ({shown.length})</button><button class="secondary" disabled={bulkBusy||statusBusy||mediaTypeBusy||archiveBusy||!selectedBookIds.length} onclick={()=>{seriesAssignmentIds=null;seriesAssignmentOpen=true}}><Stack size={17}/>Назначить серию</button><select aria-label="Статус выбранных" disabled={bulkBusy||statusBusy||!selectedBookIds.length} onchange={e=>{const status=e.currentTarget.value as ReadingStatus;e.currentTarget.value='';if(status)void bulkChange({status})}}><option value="">Статус…</option><option value="planned">Хочу прочитать</option><option value="reading">Сейчас читаю</option><option value="read">Прочитано</option><option value="unread">Не начато</option></select><select aria-label="Перенести выбранные" disabled={bulkBusy||statusBusy||mediaTypeBusy||archiveBusy||!selectedBookIds.length} onchange={e=>{const type=e.currentTarget.value;e.currentTarget.value='';if(type)void bulkChange({media_type:type})}}><option value="">Перенести в…</option><option value="book">Книги</option><option value="comic">Комиксы</option></select><button class="secondary" disabled={bulkBusy||statusBusy||mediaTypeBusy||archiveBusy||!selectedBookIds.length} onclick={()=>bulkChange({archived:view!=='archive'})}>{#if view==='archive'}<ArrowUUpLeft size={17}/>Восстановить{:else}<Archive size={17}/>В архив{/if}</button><button class="text-button" disabled={bulkBusy||statusBusy||mediaTypeBusy||archiveBusy||!selectedBookIds.length} onclick={()=>selectedBookIds=[]}>Снять выбор</button>{#if bulkBusy}<span role="status">Сохраняем…</span>{/if}</div>{/if}
     <div id="collection-filter-fields" class="filters">
      <button class="secondary local-select-toggle" disabled={bulkBusy||statusBusy} aria-label={selectingBooks?'Отменить выбор изданий':'Выбрать издания'} aria-pressed={selectingBooks} onclick={()=>{selectingBooks=!selectingBooks;selectedBookIds=[]}}>{selectingBooks?'Отменить выбор':'Выбрать'}</button>
      {#if ['archive','reading','planned','read'].includes(view)}<select aria-label={view==='archive'?'Тип издания в архиве':'Тип издания'} bind:value={archiveType}><option value="">Книги и комиксы</option><option value="book">Книги</option><option value="comic">Комиксы</option></select>{/if}
      <select aria-label="Фильтр по автору" value={authorFilter} onchange={e=>changeAuthor(e.currentTarget.value)}><option value="">Все авторы</option>{#each facetAuthors as a}<option value={a}>{a}</option>{/each}</select>
      <select aria-label="Фильтр по серии" bind:value={seriesFilter}><option value="">Все серии</option>{#if facets.hasNoSeries||seriesFilter==='__no_series__'}<option value="__no_series__">Без серии</option>{/if}{#each facetSeries as name}<option value={name}>{name}</option>{/each}</select>
      {#if !['reading','planned','read'].includes(view)}<select aria-label="Статус чтения" bind:value={statusFilter}><option value="">Все статусы</option>{#each [...new Set([...facets.statuses,...(statusFilter?[statusFilter]:[])])] as status}<option value={status}>{statusNames[status]}</option>{/each}</select>{/if}
      <select aria-label="Сортировать книги" value={displaySort} onchange={e=>setLibrarySort(e.currentTarget.value)}><option value="recent">По дате добавления</option><option value="title">По названию</option><option value="author">По автору</option><option value="series">{seriesSortScope||groupedLibrary?'По номеру в серии':'По серии'}</option><option value="progress">По позиции чтения</option><option value="format">По формату</option></select>
      {#if settings.view==='grid'||settings.view==='shelf'}<label class="cover-size-control" title="Размер обложек"><SquaresFour size={17}/><input type="range" min="120" max="230" step="10" value={settings.coverSize} oninput={e=>saveSettings({coverSize:+e.currentTarget.value})} aria-label="Размер обложек"/></label>{/if}
      {#if query||localQuery||authorFilter||seriesFilter||statusFilter||letter||archiveType||localMetadataCount}<button class="text-button" onclick={resetLocalFilters}>Сбросить<X size={14}/></button>{/if}
     </div>
    </div>

    {#if (view==='library'||view==='comics')&&recent.length&&!query&&!localQuery&&!authorFilter&&!seriesFilter&&!statusFilter&&!localMetadataCount}<section class="continue-section"><div class="section-title"><h2>Продолжить чтение</h2><button class="text-button" onclick={()=>navigate('reading')}>Все книги<ArrowRight size={17}/></button></div><div class="continue-list" use:measureContinue style={`--continue-columns:${visibleRecent.length}`}>{#each visibleRecent as b}<button class="continue-card" disabled={statusBusy||bulkBusy||archiveBusy||mediaTypeBusy} onclick={()=>openBook(b)}><Cover book={b}/><div><small>{bookAuthor(b)}</small><h3>{b.title}</h3><span class="continue-progress"><span style:width={`${b.progress||0}%`}></span></span><span class="continue-caption">Позиция в книге · {Math.round(b.progress||0)}% <ArrowRight size={17}/></span></div></button>{/each}</div></section>{/if}
    {#if view==='archive'&&!archiveItems.length}<div class="empty-state"><Archive size={38}/><h2>Архив пуст</h2><p>Уберите сюда ненужные издания через меню «…» на обложке.<br/>Их файлы, прогресс и настройки сохранятся.</p></div>{:else if view==='archive'&&!scopedBooks.length}<div class="empty-state"><Archive size={38}/><h2>В архиве нет изданий этого типа</h2><button onclick={()=>archiveType=''}>Показать весь архив</button></div>{:else if !scopedBooks.length&&!['reading','planned','read'].includes(view)}<div class="empty-state first-library"><BookOpen size={64} weight="thin"/><h2>{comicView?'Здесь будут ваши комиксы':'Здесь начинается ваша библиотека'}</h2><p>{comicView?'Перетащите сюда CBZ, CBR или целую папку. Для PDF нажмите «…» у обложки и выберите «В комиксы».':'Перетащите сюда книги или целую папку. Поддерживаются FB2, FB2.zip, EPUB, TXT и PDF.'}</p><div><button class="primary" onclick={()=>fileInput.click()}><FilePlus size={20}/>Выбрать книги</button><button onclick={()=>folderInput.click()}><FolderPlus size={20}/>Добавить папку</button></div><button class="text-button" onclick={()=>navigate('catalogs')}>Или загляните в OPDS-каталоги<ArrowRight size={17}/></button></div>
    {:else if ['reading','planned','read'].includes(view)&&!viewCount&&!archiveType}<div class="empty-state"><BookOpen size={40}/><h2>{view==='planned'?'В планах пока пусто':view==='read'?'Завершённых изданий пока нет':'Сейчас ничего не читается'}</h2><p>{view==='planned'?'Нажмите сердечко рядом с меню «…» у книги или комикса.':view==='read'?'Отметьте завершённое издание через меню «…» или подсказку в конце чтения.':'Откройте книгу или комикс — они появятся здесь.'}</p></div>{:else if !shown.length}<div class="empty-state"><MagnifyingGlass size={40}/><h2>Пока ничего не нашлось</h2><p>Попробуйте другой запрос или снимите фильтры.</p></div>
    {:else}
     {#each libraryGroups as group (group.key)}<section class="local-series-group" aria-label={groupedByAuthor?(group.name||'Автор не указан'):groupedLibrary?(group.name||'Без серии'):undefined}>
      {#if groupedLibrary||groupedByAuthor}<div class="local-series-heading"><h2>{#if groupedByAuthor&&!group.name}Автор не указан{:else}<button onclick={()=>{if(groupedByAuthor)changeAuthor(group.name);else seriesFilter=group.name||'__no_series__';selectedBookIds=[]}}>{group.name||'Без серии'}</button>{/if}<span>{group.books.length}</span></h2></div>{/if}
      {#if !settings.readerGuideHidden&&group.books.some(book=>book.is_reader_guide)}<div class="guide-shelf-action"><span>Руководство читателя всегда доступно в «Помощи».</span><button class="text-button" disabled={guideBusy} onclick={hideReaderGuide}>Скрыть с полки</button></div>{/if}
      <LibraryBooks books={group.books} view={settings.view} coverSize={settings.coverSize} selectedId={selected?.id||''} selecting={selectingBooks} selectedIds={selectedBookIds} busy={mediaTypeBusy||archiveBusy||bulkBusy||statusBusy} sortKey={displaySort} sortDirection={displayDirection} onselect={book=>selected=book} onread={openBook} onstatus={setStatus} onplanned={togglePlanned} onmedia={setMediaType} onarchive={setArchived} onseries={assignSeries} oncheck={selectBook} onsort={tableSort}/>
     </section>{/each}
    {/if}
   {/if}
  </main>
  <footer class="library-footer"><span><BookOpen size={15}/>{view==='catalogs'?'Новые истории совсем рядом':'У каждой книги — своё время'}</span><button class="text-button" onclick={()=>folderInput.click()}><FolderPlus size={16}/>Добавить папку</button><span>FB2 · EPUB · TXT · PDF · CBZ · CBR</span></footer>
 </div>
 {#if selected||remoteSelected}{@const b=selected||remoteSelected}<aside class="book-detail"><button class="detail-close icon-button" aria-label="Закрыть карточку" onclick={()=>{selected=null;remoteSelected=null}}><X size={22}/></button><Cover book={b} className="detail-cover"/><span class="eyebrow">{selected?.archived?'В АРХИВЕ':selected||remoteSelected?.local_book_id?'В ВАШЕЙ БИБЛИОТЕКЕ':'ИЗ OPDS-КАТАЛОГА'}</span><h2>{b.title}</h2>{#if selected||!remoteDestinations.some(item=>item.kind==='author')}<p class="detail-author">{bookAuthor(b)}</p>{/if}{#if selected}<div class="detail-progress"><span>Позиция в книге · {Math.round(selected.progress||0)}%</span><div class="progress-track"><span style:width={`${selected.progress||0}%`}></span></div></div><button class="primary wide" disabled={statusBusy||bulkBusy||archiveBusy||mediaTypeBusy} onclick={()=>openBook(selected)}><BookOpen size={20}/>{selected.progress>0?'Продолжить чтение':'Открыть книгу'}</button><button class="secondary wide planned-action" class:is-planned={normalizeReadStatus(selected.status)==='planned'} aria-pressed={normalizeReadStatus(selected.status)==='planned'} title={normalizeReadStatus(selected.status)==='planned'?'Убрать из планов':'Добавить в «Хочу прочитать»'} disabled={statusBusy||mediaTypeBusy||archiveBusy||bulkBusy} onclick={()=>togglePlanned(selected)}><Heart size={19} weight={normalizeReadStatus(selected.status)==='planned'?'fill':'regular'}/>{normalizeReadStatus(selected.status)==='planned'?'В планах':'Хочу прочитать'}</button><label class="detail-status-label" for="book-status">Статус чтения</label><select id="book-status" aria-label="Статус книги" disabled={statusBusy||mediaTypeBusy||archiveBusy||bulkBusy} value={normalizeReadStatus(selected.status)} onchange={e=>setStatus(selected,e.currentTarget.value)}><option value="unread">Не начато</option><option value="reading">Сейчас читаю</option><option value="planned">Хочу прочитать</option><option value="read">Прочитано</option></select><div class="detail-media-type"><span>Раздел библиотеки</span><div class="segmented" role="group" aria-label="Раздел библиотеки"><button class:active={mediaType(selected)==='book'} aria-pressed={mediaType(selected)==='book'} disabled={mediaTypeBusy||archiveBusy||bulkBusy||statusBusy} onclick={()=>setMediaType(selected,'book')}><Books size={16}/>Книги</button><button class:active={mediaType(selected)==='comic'} aria-pressed={mediaType(selected)==='comic'} disabled={mediaTypeBusy||archiveBusy||bulkBusy||statusBusy} onclick={()=>setMediaType(selected,'comic')}><Stack size={16}/>Комиксы</button></div></div>{#if selected.series}<p class="detail-series">{selected.series}{selected.series_index!=null?` · ${selected.series_index}`:''}</p>{/if}<!-- Import decisions remain visible after the notification disappears. -->{#if selected.text_encoding}<p class="muted small">Кодировка: {selected.text_encoding}</p>{/if}{#each selected.import_warnings||[] as warning}<p class="muted small">{warning}</p>{/each}<p class="detail-annotation">{selected.annotation||'У этой книги нет аннотации. Самое интересное — под обложкой.'}</p><div class="detail-facts"><span>{selected.format?.toUpperCase()}</span><span>{selected.language||'Язык не указан'}</span></div><button class="secondary wide detail-archive" disabled={archiveBusy||bulkBusy||mediaTypeBusy||statusBusy} onclick={()=>setArchived(selected,!selected.archived)}>{#if selected.archived}<ArrowUUpLeft size={18}/>Восстановить из архива{:else}<Archive size={18}/>Убрать в архив{/if}</button><button class="text-button danger" onclick={()=>deleteBook=selected}><Trash size={17}/>Удалить навсегда</button>{:else}{#if remoteDestinations.length}<div class="opds-related">{#each ['author','series'] as kind}{@const destinations=remoteDestinations.filter(item=>item.kind===kind)}{#if destinations.length}<div class="opds-related-group"><h3>{kind==='author'?'Авторы':'Серии'}</h3>{#each destinations as destination}<button class="opds-related-link" disabled={!destination.url&&!activeSearch&&!(flibustaActive&&kind==='series'&&permanentTabs.some(tab=>tab.id==='series'))} onclick={()=>openRelated(destination)}>{#if kind==='author'}<Users size={17}/>{:else}<Stack size={17}/>{/if}<span><strong>{destination.name}</strong><small>{destination.url?(kind==='author'?'Все книги автора':'Книги серии'):(kind==='author'?'Найти автора':'Найти серию')}{destination.position?` · № ${destination.position}`:''}</small></span><ArrowRight size={16}/></button>{/each}</div>{/if}{/each}</div>{/if}<button class="primary wide" disabled={downloads[remoteSelected.id]||(!remoteSelected.local_book_id&&(!remoteSelected.acquisitions?.length||batchBusy))} onclick={()=>download(remoteSelected)}>{#if remoteSelected.local_book_id}<BookOpen size={20}/>Читать{:else if !remoteSelected.acquisitions?.length}{remoteSelected.unavailable_reason||'Нет поддерживаемого формата'}{:else}<Download size={20}/>{downloads[remoteSelected.id]?'Скачиваем…':'В мою библиотеку'}{/if}</button>{#if !remoteSelected.local_book_id&&!remoteSelected.acquisitions?.length}<p class="muted small">Эта книга есть в каталоге, но пока доступна только в неподдерживаемом формате. Переплёт читает FB2, FB2.zip, EPUB, TXT, PDF, CBZ и CBR.</p>{/if}{#if remoteSizeLabel(remoteSelected)}<p class="muted small" title={remoteSizeTitle(remoteSelected)}>{remoteSizeLabel(remoteSelected)}</p>{/if}<p class="detail-annotation">{remoteSelected.summary||'Описание не предоставлено каталогом.'}</p>{/if}</aside>{/if}
</div>
{/if}

{#if savedPanel&&currentCatalog}<div class="modal-backdrop"><div class="opds-saved-panel" use:dialogFocus role="dialog" aria-modal="true" aria-label={savedPanel==='history'?'История каталога':'Сохранённые разделы'}><div class="panel-heading"><div><span class="eyebrow">{currentCatalog.name}</span><h2>{savedPanel==='history'?'История каталога':'Сохранённые разделы'}</h2></div><button class="icon-button" aria-label="Закрыть историю и закладки" onclick={()=>savedPanel=null}><X size={22}/></button></div><div class="opds-saved-list">{#each savedLocations as location}<div class="opds-saved-row"><button class="opds-saved-open" onclick={()=>openSaved(location)}><strong>{location.title}</strong>{#if location.requestQuery||location.query}<span>Поиск: {location.requestQuery||location.query}</span>{/if}<small>{new Date(location.timestamp).toLocaleString('ru-RU',{dateStyle:'short',timeStyle:'short'})}</small></button>{#if savedPanel==='bookmarks'}<button class="icon-button" aria-label={`Удалить закладку ${location.title}`} onclick={()=>removeBookmark(location)}><X size={18}/></button>{/if}</div>{:else}<p class="muted">{savedPanel==='bookmarks'?'Сохраните любимого автора или серию значком закладки справа в адресной строке.':'Открытые разделы появятся здесь.'}</p>{/each}</div><p class="muted small">Сохраняются адрес раздела, поиск и положение прокрутки на этом компьютере.</p></div></div>{/if}

{#if dragging}<div class="drop-overlay"><div><UploadSimple size={58} weight="light"/><h2>Отпустите — и книги окажутся на полке</h2><p>Отдельные файлы или целая папка · FB2, FB2.zip, EPUB, TXT, PDF, CBZ, CBR</p></div></div>{/if}
{#if importBusy}<div class="import-progress"><CloudArrowDown size={21}/>{importMessage}</div>{/if}
{#if toast}<div class="toast" role="status"><CheckCircle size={21}/><span>{toast}</span><button class="icon-button" aria-label="Закрыть уведомление" onclick={()=>toast=''}><X size={17}/></button></div>{/if}

{#if settingsOpen}<div class="modal-backdrop"><div class="settings-modal" role="dialog" aria-modal="true" aria-label="Настройки приложения"><div class="panel-heading"><div><span class="eyebrow">ПЕРЕПЛЁТ ПОД ВАШ ВКУС</span><h2>Обустроим библиотеку</h2></div><button class="icon-button" aria-label="Закрыть настройки" onclick={()=>settingsOpen=false}><X size={23}/></button></div><section class="library-scale-setting" aria-label="Масштаб библиотеки"><div class="range-label"><label for="library-scale">Размер интерфейса библиотеки</label><output for="library-scale">{Math.max(100,Math.min(150,Number(settings.libraryScale)||115))}%</output></div><input id="library-scale" type="range" min="100" max="150" step="5" value={Math.max(100,Math.min(150,Number(settings.libraryScale)||115))} oninput={e=>saveSettings({libraryScale:+e.currentTarget.value})}/><div class="scale-endpoints"><span>Компактнее</span><span>Крупнее</span></div><p>Увеличивает названия, фильтры, кнопки и обложки в библиотеке и OPDS. Размер текста внутри книги настраивается отдельно.</p></section><div class="control-label">Оформление</div><div class="theme-preview-grid">{#each themes as t}<button class:selected={settings.theme===t.id} class="theme-preview" data-swatch={t.id} onclick={()=>saveSettings({theme:t.id})}><span class="theme-sample"><BookOpen size={29} weight="light"/>{#if settings.theme===t.id}<CheckCircle size={20} weight="fill"/>{/if}</span><strong>{t.name}</strong><small>{t.description}</small></button>{/each}</div><div class="settings-columns"><div><label class="control-label" for="default-font">Шрифт для чтения</label><select id="default-font" value={settings.font} onchange={e=>saveSettings({font:e.currentTarget.value})}>{#each fonts as f}<option value={f}>{f}</option>{/each}</select><p class="font-preview" style:font-family={settings.font}>Приятно остаться наедине<br/>с хорошей книгой.</p></div><div><div class="control-label">Расположение страниц</div><div class="segmented layout-options">{#each [{id:'single',name:'Одна'},{id:'spread',name:'Разворот'},{id:'scroll',name:'Свиток'}] as l}<button class:active={settings.layout===l.id} onclick={()=>saveSettings({layout:l.id})}>{l.name}</button>{/each}</div><div class="range-label"><label for="default-size">Размер текста</label><span>{settings.fontSize} px</span></div><input id="default-size" type="range" min="15" max="38" value={settings.fontSize} oninput={e=>saveSettings({fontSize:+e.currentTarget.value})}/><label class="check-control"><input type="checkbox" checked={settings.texture} onchange={e=>saveSettings({texture:e.currentTarget.checked})}/>Текстура бумаги</label></div></div><div class="keyboard-help"><strong>Под рукой</strong><span><kbd>←</kbd><kbd>→</kbd> Страницы</span><span><kbd>Space</kbd> Вперёд</span><span><kbd>T</kbd> Содержание</span><span><kbd>F</kbd> Фокус</span><span><kbd>Ctrl</kbd><kbd>Space</kbd> Озвучка</span></div><p class="muted small">Поля, ширина страницы, межстрочный интервал и голос — в быстрых настройках во время чтения. Изменения сохраняются автоматически.</p></div></div>{/if}
{#if catalogModal}<div class="modal-backdrop"><div class="small-modal" role="dialog" aria-modal="true" aria-label="Добавить каталог"><div class="panel-heading"><h2>Новый OPDS-каталог</h2><button class="icon-button" aria-label="Закрыть" onclick={()=>catalogModal=false}><X size={22}/></button></div><p class="muted">Каталог будет открываться рядом с вашей библиотекой.</p><form onsubmit={e=>{e.preventDefault();addCatalog()}}><label for="catalog-name">Название</label><input id="catalog-name" bind:value={catalogName} placeholder="Моя любимая библиотека" required/><label for="catalog-url">Адрес OPDS</label><input id="catalog-url" type="url" bind:value={catalogUrl} placeholder="https://example.org/opds" required/><button class="primary wide" type="submit" disabled={catalogSaving}>{catalogSaving?'Добавляем…':'Добавить каталог'}</button></form></div></div>{/if}
{#if deleteBook}<div class="modal-backdrop"><div class="small-modal" role="dialog" aria-modal="true" aria-label="Удалить книгу"><div class="panel-heading"><h2>Убрать книгу с полки?</h2><button class="icon-button" aria-label="Отмена" onclick={()=>deleteBook=null}><X size={22}/></button></div><p>«{deleteBook.title}» будет удалена из библиотеки вместе с прогрессом и закладками. Исходный файл, который вы добавили, останется на месте.</p><div class="modal-actions"><button onclick={()=>deleteBook=null}>Оставить</button><button class="danger-solid" onclick={removeBook}>Удалить</button></div></div></div>{/if}











